        "Hx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8f" +
        "Hx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8f" +
        "Hx8fHh4fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8eHh4fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx4eHh4fHx8f" +
        "Hx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHh4eHh4fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8eHh4eHh8fHx8fHx8fHx8fHx8f" +
        "Hx8fHx8fHx8fHx8gIB4eHh4eHx8fHx8fHx8fHx8fHx8fHx8fHx8fHx8fHyAg";

    private static readonly byte[] Blob = Convert.FromBase64String(BlobBase64);

    // Offsets of each table (named height x width like dav1d, i.e. the transposed dimensions of the
    // transform the table serves) within the blob; each table holds 15 levels x 2 planes x h*w bytes.
    private static readonly Dictionary<(int H, int W), int> Offsets = new()
    {
        [(4, 4)] = 0,
        [(4, 8)] = 480,
        [(4, 16)] = 1440,
        [(8, 4)] = 3360,
        [(8, 8)] = 4320,
        [(8, 16)] = 6240,
        [(8, 32)] = 10080,
        [(16, 4)] = 17760,
        [(16, 8)] = 19680,
        [(16, 16)] = 23520,
        [(16, 32)] = 31200,
        [(32, 8)] = 46560,
        [(32, 16)] = 54240,
        [(32, 32)] = 69600,
    };

    /// <summary>
    /// Gets the weight table for one transform block, or an empty span when the level applies no
    /// weighting. The returned span is indexed by the coefficient index.
    /// </summary>
    /// <param name="level">The frame's matrix level for the plane (0..15).</param>
    /// <param name="plane">The plane index (0 for luma, 1 or 2 for chroma).</param>
    /// <param name="transformSize">The transform size.</param>
    /// <returns>The weights, or empty for level 15.</returns>
    public static ReadOnlySpan<byte> Get(int level, int plane, Av1TransformSize transformSize)
    {
        if (level >= 15)
        {
            return default;
        }

        // The table serves the transform's coded area in the transposed coefficient layout.
        int codedWidth = Math.Min(transformSize.GetWidth(), 32);
        int codedHeight = Math.Min(transformSize.GetHeight(), 32);
        int cells = codedWidth * codedHeight;
        int offset = Offsets[(codedHeight, codedWidth)] + (((level * 2) + (plane == 0 ? 0 : 1)) * cells);
        return Blob.AsSpan(offset, cells);
    }
}
